-- PostgreSQL CASE-SENSITIVE physical identifiers: MSSV BIT242181 prefixes all tables/columns.
-- Safe to run repeatedly because of IF NOT EXISTS.
CREATE TABLE IF NOT EXISTS "BIT242181_DishCategories" (
    "BIT242181_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT242181_Name" VARCHAR(120) NOT NULL,
    "BIT242181_Description" VARCHAR(1000)
);
CREATE TABLE IF NOT EXISTS "BIT242181_Dishes" (
    "BIT242181_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT242181_Name" VARCHAR(160) NOT NULL,
    "BIT242181_Price" NUMERIC(12,2) NOT NULL CHECK ("BIT242181_Price" > 0),
    "BIT242181_PreparationTime" INTEGER NOT NULL CHECK ("BIT242181_PreparationTime" > 0),
    "BIT242181_IsAvailable" BOOLEAN NOT NULL DEFAULT TRUE,
    "BIT242181_Description" VARCHAR(2000),
    "BIT242181_DishCategoryId" BIGINT NOT NULL REFERENCES "BIT242181_DishCategories" ("BIT242181_Id") ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS "BIT242181_DishImages" (
    "BIT242181_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT242181_ImageUrl" VARCHAR(2048) NOT NULL,
    "BIT242181_IsThumbnail" BOOLEAN NOT NULL DEFAULT FALSE,
    "BIT242181_DishId" BIGINT NOT NULL REFERENCES "BIT242181_Dishes" ("BIT242181_Id") ON DELETE CASCADE
);
-- One category name globally, one dish name per category (case-insensitive).
CREATE UNIQUE INDEX IF NOT EXISTS "BIT242181_uq_category_name" ON "BIT242181_DishCategories" (LOWER("BIT242181_Name"));
CREATE UNIQUE INDEX IF NOT EXISTS "BIT242181_uq_dish_category_name" ON "BIT242181_Dishes" ("BIT242181_DishCategoryId", LOWER("BIT242181_Name"));
-- DB guarantee: at most ONE thumbnail for a dish.
CREATE UNIQUE INDEX IF NOT EXISTS "BIT242181_uq_one_thumbnail" ON "BIT242181_DishImages" ("BIT242181_DishId") WHERE "BIT242181_IsThumbnail" = TRUE;
CREATE INDEX IF NOT EXISTS "BIT242181_idx_dish_category" ON "BIT242181_Dishes" ("BIT242181_DishCategoryId");
CREATE INDEX IF NOT EXISTS "BIT242181_idx_dish_price" ON "BIT242181_Dishes" ("BIT242181_Price");
CREATE INDEX IF NOT EXISTS "BIT242181_idx_image_dish" ON "BIT242181_DishImages" ("BIT242181_DishId");

-- Seed data only when its target table is empty on startup.
-- Avoid PL/pgSQL DO blocks: Spring JDBC SQL initializer splits on semicolons.
INSERT INTO "BIT242181_DishCategories" ("BIT242181_Name", "BIT242181_Description")
SELECT demo.name, demo.description FROM (VALUES
    ('Vietnamese Classics', 'Authentic dishes inspired by Vietnamese home kitchens'),
    ('Rice & Noodles', 'Comforting rice dishes and warm noodles'),
    ('Drinks & Desserts', 'Refreshing drinks and sweet treats')
) AS demo(name, description)
WHERE NOT EXISTS (SELECT 1 FROM "BIT242181_DishCategories")
ON CONFLICT DO NOTHING;

INSERT INTO "BIT242181_Dishes" ("BIT242181_Name", "BIT242181_Price", "BIT242181_PreparationTime", "BIT242181_IsAvailable", "BIT242181_Description", "BIT242181_DishCategoryId")
SELECT seed.name, seed.price, seed.minutes, seed.available, seed.description, category."BIT242181_Id"
FROM (VALUES
    ('Phở bò Hà Nội', 55000.00, 18, TRUE, 'Slow-simmered beef broth, rice noodles and fresh herbs', 'Rice & Noodles'),
    ('Bún chả', 60000.00, 20, TRUE, 'Grilled pork with rice noodles, herbs and dipping sauce', 'Vietnamese Classics'),
    ('Cơm tấm sườn', 65000.00, 25, TRUE, 'Broken rice with marinated grilled pork', 'Rice & Noodles'),
    ('Gỏi cuốn', 38000.00, 12, TRUE, 'Fresh spring rolls served with peanut sauce', 'Vietnamese Classics'),
    ('Cà phê sữa đá', 30000.00, 5, TRUE, 'Vietnamese iced coffee with condensed milk', 'Drinks & Desserts'),
    ('Chè đậu đỏ', 35000.00, 10, FALSE, 'Sweet red bean dessert', 'Drinks & Desserts'),
    ('Bánh mì thịt', 42000.00, 8, TRUE, 'Crispy baguette with grilled meat and pickles', 'Vietnamese Classics')
) AS seed(name, price, minutes, available, description, category)
JOIN "BIT242181_DishCategories" category ON category."BIT242181_Name" = seed.category
WHERE NOT EXISTS (SELECT 1 FROM "BIT242181_Dishes")
ON CONFLICT DO NOTHING;

-- Demo image URLs (remote: Internet connection required to display them).
INSERT INTO "BIT242181_DishImages" ("BIT242181_ImageUrl", "BIT242181_IsThumbnail", "BIT242181_DishId")
SELECT seed.url, seed.thumbnail, dish."BIT242181_Id"
FROM (VALUES
    ('Phở bò Hà Nội', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=900&auto=format&fit=crop', TRUE),
    ('Phở bò Hà Nội', 'https://images.unsplash.com/photo-1555126634-323283e090fa?w=900&auto=format&fit=crop', FALSE),
    ('Bún chả', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=900&auto=format&fit=crop', TRUE),
    ('Cơm tấm sườn', 'https://images.unsplash.com/photo-1547592180-85f173990554?w=900&auto=format&fit=crop', TRUE),
    ('Gỏi cuốn', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=900&auto=format&fit=crop', TRUE),
    ('Cà phê sữa đá', 'https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=900&auto=format&fit=crop', TRUE),
    ('Bánh mì thịt', 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=900&auto=format&fit=crop', TRUE)
) AS seed(dish_name, url, thumbnail)
JOIN "BIT242181_Dishes" dish ON dish."BIT242181_Name" = seed.dish_name
WHERE NOT EXISTS (SELECT 1 FROM "BIT242181_DishImages") AND NOT EXISTS (
    SELECT 1 FROM "BIT242181_DishImages" image
    WHERE image."BIT242181_DishId" = dish."BIT242181_Id" AND image."BIT242181_ImageUrl" = seed.url
);
